-- =====================================================================
-- J-LAS patch: viet lai meo nho / luu y / mo ta cua lo trinh Onyomi (2026-10-25).
-- Chi UPDATE van ban (conversion_rule, rule_pattern buoc 3-4, loi giai thich cau hoi); khong xoa cau tra
-- loi hay tien do cua nguoi hoc. Chay lai an toan. DB tao moi tu onyomi_canonical.sql da co san noi dung nay.
-- Noi dung lay tu scripts/onyomi/onyomi_rules.json (nguon chinh); sua o do roi chay generate_onyomi.py.
-- =====================================================================
SET NAMES utf8mb4;
SET @tb = (SELECT id FROM textbook WHERE title = 'Amon / Âm On-Kun' ORDER BY id LIMIT 1);

UPDATE conversion_rule SET description = 'Âm đầu C (không phải CH) thường tương ứng với hàng カ (K) trong âm On.', tip = 'Đổi C thành K rồi đọc: Công 工 → コウ, Cổ 古 → コ, Các 各 → カク.', note = 'C và K trong Hán Việt là cùng một âm “cờ”, chỉ khác cách viết: trước i, e, ê, y viết K (Kim, Kế, Kỳ), còn lại viết C (Công, Cổ, Ca). Vì vậy C → K và K → K thực chất là một quy tắc.' WHERE title = 'Âm đầu C → K' AND lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id = l.unit_id WHERE u.textbook_id = @tb);
UPDATE rule_pattern rp JOIN conversion_rule cr ON cr.id = rp.rule_id SET rp.content = 'Đổi C thành K rồi đọc: Công 工 → コウ, Cổ 古 → コ, Các 各 → カク.' WHERE rp.step = 3 AND cr.title = 'Âm đầu C → K' AND cr.lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id = l.unit_id WHERE u.textbook_id = @tb);
UPDATE rule_pattern rp JOIN conversion_rule cr ON cr.id = rp.rule_id SET rp.content = 'C và K trong Hán Việt là cùng một âm “cờ”, chỉ khác cách viết: trước i, e, ê, y viết K (Kim, Kế, Kỳ), còn lại viết C (Công, Cổ, Ca). Vì vậy C → K và K → K thực chất là một quy tắc.' WHERE rp.step = 4 AND cr.title = 'Âm đầu C → K' AND cr.lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id = l.unit_id WHERE u.textbook_id = @tb);
UPDATE conversion_rule SET description = 'Âm đầu K thường giữ hàng カ (K); đôi khi thành ガ (G).', tip = 'K giữ nguyên là K: Kim 金 → キン, Kỳ 期 → キ, Kiến 見 → ケン.', note = 'Đôi khi K thành G (thêm dấu ゛): Kỹ 技 → ギ, như trong 技術 (ぎじゅつ, kỹ thuật).' WHERE title = 'Âm đầu K → K' AND lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id = l.unit_id WHERE u.textbook_id = @tb);
UPDATE rule_pattern rp JOIN conversion_rule cr ON cr.id = rp.rule_id SET rp.content = 'K giữ nguyên là K: Kim 金 → キン, Kỳ 期 → キ, Kiến 見 → ケン.' WHERE rp.step = 3 AND cr.title = 'Âm đầu K → K' AND cr.lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id = l.unit_id WHERE u.textbook_id = @tb);
UPDATE rule_pattern rp JOIN conversion_rule cr ON cr.id = rp.rule_id SET rp.content = 'Đôi khi K thành G (thêm dấu ゛): Kỹ 技 → ギ, như trong 技術 (ぎじゅつ, kỹ thuật).' WHERE rp.step = 4 AND cr.title = 'Âm đầu K → K' AND cr.lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id = l.unit_id WHERE u.textbook_id = @tb);
UPDATE conversion_rule SET description = 'Âm đầu QU thường tương ứng với hàng カ (K); một số chữ thành ガ (G).', tip = 'Bỏ chữ “u” sau Q rồi đọc như K: Quốc 国 → コク, Quả 果 → カ, Quán 館 → カン.', note = 'Đôi khi QU thành G: Quân 軍 → グン.' WHERE title = 'Âm đầu QU → K' AND lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id = l.unit_id WHERE u.textbook_id = @tb);
UPDATE rule_pattern rp JOIN conversion_rule cr ON cr.id = rp.rule_id SET rp.content = 'Bỏ chữ “u” sau Q rồi đọc như K: Quốc 国 → コク, Quả 果 → カ, Quán 館 → カン.' WHERE rp.step = 3 AND cr.title = 'Âm đầu QU → K' AND cr.lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id = l.unit_id WHERE u.textbook_id = @tb);
UPDATE rule_pattern rp JOIN conversion_rule cr ON cr.id = rp.rule_id SET rp.content = 'Đôi khi QU thành G: Quân 軍 → グン.' WHERE rp.step = 4 AND cr.title = 'Âm đầu QU → K' AND cr.lesson_id IN (SELECT l.id FROM lesson l JOIN unit u ON u.id = l.unit_id WHERE u.textbook_id = @tb);
